sf_lsoa_a_roads &lt;- sf_lsoa |&gt;
  st_transform(4326) |&gt;
  left_join(df_lsoa |&gt; select(LSOA21CD, a_road_length_m), by = "LSOA21CD") |&gt;
  mutate(
    has_a_roads = a_road_length_m &gt; 0,
    fill_colour = if_else(has_a_roads, "#2166ac", "#ff964f")
  )

bb &lt;- sf_lsoa_a_roads |&gt; st_bbox()

make_basemap() |&gt;
  fitBounds(bb[["xmin"]], bb[["ymin"]], bb[["xmax"]], bb[["ymax"]]) |&gt;
  addPolygons(
    data = sf_lsoa_a_roads,
    fillColor = ~fill_colour,
    fillOpacity = 0.6,
    color = "white",
    weight = 0.5,
    smoothFactor = 0.5
  ) |&gt;
  addLegend(
    position = "topright",
    colors = c("#2166ac", "#ff964f"),
    labels = c("Some A roads", "No A roads"),
    opacity = 0.6,
    title = NULL
  )




Figure 6: LSOAs with and without A roads








This is to illustrate how LSOA boundaries are drawn in relation to A roads. There’s a concern that LSOA boundaries drawn along A roads, with for example, one adjacent LSOA including the A Road and another adjacent LSOA not including the A Road. A manual inspection of Figure 6 indicates that there aren’t as many instances of this as feared. Hwoever, there are some, for example at Netherthorpe, Darnall, and Greenhill. A simple fix could be to include a very small buffer (e.g. 10m) for the LSOA boundaries used in the calculations. This would mean some double counting of road lengths, but arguably a better variable for our clustering. Alternatively we could shift from a numeric to a categorical a_road variable: “adjacent”, “through”, “none”.


Code
tar_load(df_lsoa_road_network_near)

# List of LSOAs adjacent to A road (not containing) 
df_lsoa_a_road_adjacent &lt;- df_lsoa_road_network_near |&gt; 
  filter(near_a_road_length_m !=0) |&gt; 
  anti_join(
    df_lsoa |&gt;
      filter(a_road_length_m != 0),
    by = join_by(LSOA21CD)
  )

n_lsoa_a_road_adjacent &lt;- df_lsoa_a_road_adjacent |&gt; 
  count() |&gt; 
  pull()

sf_lsoa_a_road_adjacent &lt;- sf_lsoa |&gt;
  st_transform(4326) |&gt;
  left_join(
    df_lsoa_a_road_adjacent |&gt; 
      select(LSOA21CD, near_a_road_length_m),
    by = "LSOA21CD"
  ) |&gt;
  mutate(
    a_road_adjacent = !is.na(near_a_road_length_m),
    fill_colour = if_else(a_road_adjacent, "#2166ac", "#ff964f")
  )

bb &lt;- sf_lsoa_a_road_adjacent |&gt; st_bbox()

make_basemap() |&gt;
  fitBounds(bb[["xmin"]], bb[["ymin"]], bb[["xmax"]], bb[["ymax"]]) |&gt;
  addPolygons(
    data = sf_lsoa_a_road_adjacent,
    fillColor = ~fill_colour,
    fillOpacity = 0.6,
    color = "white",
    weight = 0.5,
    smoothFactor = 0.5
  ) |&gt;
  addLegend(
    position = "topright",
    colors = c("#2166ac", "#ff964f"),
    labels = c("Adjacent to A roads", "Not adjacent to A roads"),
    opacity = 0.6,
    title = NULL
  )




Figure 7: LSOAs adjacent (10m) to A roads








A buffer of 10m results identifies 12 LSOAs that are adjacent to A roads (as illustrated in Figure 7).


