  geom_histogram(bins = 20, colour = "white") +
  scale_x_continuous(labels  = scales::comma) +
  labs(
    x = "A road length (m)",
    y = "LSOAs",
    title = str_c(
      round((n_zero_a_road_length_m/n_lsoa)*100),
      "% of LSOAs (",
      n_zero_a_road_length_m, "/", n_lsoa,
